12:import java.util.ArrayList;
13:import java.util.List;
14:import java.util.Objects;
15:import java.util.Optional;
16:import java.util.Set;
17:
18:/** Provider-shape parser. The event id comes only from the guarded request. */
19:public final class EventStatisticsV2Parser {
20:
21:    public static final String PARSER_VERSION = "event-statistics-v2";
22:    private static final Set<String> ROOT_FIELDS = Set.of("statistics");
23:    private static final Set<String> PERIOD_FIELDS = Set.of("period", "groups");
24:    private static final Set<String> GROUP_FIELDS = Set.of("groupName", "statisticsItems");
25:    private static final Set<String> ITEM_FIELDS = Set.of(
26:            "key", "name", "home", "away", "compareCode", "statisticsType",
27:            "valueType", "homeValue", "awayValue", "renderType");
28:
29:    public J5ParseResult<EventStatistics> parse(
30:            long snapshotId,
31:            long expectedEventId,
32:            RawPayloadEvidence payload,
33:            Instant receivedAt) {
34:        J5JsonParserSupport.requirePositiveEventId(expectedEventId);
35:        J5ParseEvidence evidence = evidence(snapshotId, payload, receivedAt);
36:        JsonNode root;
37:        try {
38:            root = J5JsonParserSupport.readTree(payload.bytes());
39:        }
40:        catch (JacksonException exception) {
41:            return failed(J5ParseStatus.UNEXPECTED_CONTENT, evidence,
42:                    J5ParseProblem.Code.INVALID_JSON, "$",
43:                    "The payload is not valid unambiguous JSON");
44:        }
45:        List<J5ParseWarning> warnings = new ArrayList<>();
46:        List<J5ParseProblem> problems = new ArrayList<>();
47:        if (!J5JsonParserSupport.requiredObject(root, "$", problems)) {
48:            return incompatible(evidence, warnings, problems);
49:        }
50:        J5JsonParserSupport.warnUnknownFields(root, ROOT_FIELDS, "$", warnings);
51:        JsonNode periods = root.get("statistics");
52:        if (!J5JsonParserSupport.requiredArray(periods, "$.statistics", problems)) {
53:            return incompatible(evidence, warnings, problems);
54:        }
55:
56:        List<EventStatisticMetric> metrics = new ArrayList<>();
57:        Completeness completeness = new Completeness();
58:        for (int p = 0; p < periods.size(); p++) {
59:            JsonNode periodNode = periods.get(p);
60:            String periodPath = "$.statistics[" + p + "]";
61:            if (!J5JsonParserSupport.requiredObject(periodNode, periodPath, problems)) {
62:                continue;
63:            }
64:            J5JsonParserSupport.warnUnknownFields(periodNode, PERIOD_FIELDS, periodPath, warnings);
65:            String period = J5JsonParserSupport.requiredText(
66:                    periodNode.get("period"), periodPath + ".period", 32, problems);
67:            JsonNode groups = periodNode.get("groups");
68:            if (!J5JsonParserSupport.requiredArray(groups, periodPath + ".groups", problems)) {
69:                continue;
70:            }
71:            for (int g = 0; g < groups.size(); g++) {
72:                JsonNode groupNode = groups.get(g);
73:                String groupPath = periodPath + ".groups[" + g + "]";
74:                if (!J5JsonParserSupport.requiredObject(groupNode, groupPath, problems)) {
75:                    continue;
76:                }
77:                J5JsonParserSupport.warnUnknownFields(groupNode, GROUP_FIELDS, groupPath, warnings);
78:                String groupName = J5JsonParserSupport.requiredText(
79:                        groupNode.get("groupName"), groupPath + ".groupName", 100, problems);
80:                JsonNode items = groupNode.get("statisticsItems");
81:                if (!J5JsonParserSupport.requiredArray(
82:                        items, groupPath + ".statisticsItems", problems)) {
83:                    continue;
84:                }
85:                for (int i = 0; i < items.size(); i++) {
86:                    JsonNode item = items.get(i);
87:                    String itemPath = groupPath + ".statisticsItems[" + i + "]";
88:                    if (!J5JsonParserSupport.requiredObject(item, itemPath, problems)) {
89:                        continue;
90:                    }
91:                    J5JsonParserSupport.warnUnknownFields(item, ITEM_FIELDS, itemPath, warnings);
92:                    String key = J5JsonParserSupport.requiredText(
93:                            item.get("key"), itemPath + ".key", 100, problems);
94:                    String name = J5JsonParserSupport.requiredText(
95:                            item.get("name"), itemPath + ".name", 150, problems);
96:                    Optional<String> home = J5JsonParserSupport.optionalScalarText(
97:                            item.get("home"), itemPath + ".home", 100, warnings, problems);
98:                    Optional<String> away = J5JsonParserSupport.optionalScalarText(
99:                            item.get("away"), itemPath + ".away", 100, warnings, problems);
100:                    completeness.expect(itemPath + ".home", home.isPresent());
101:                    completeness.expect(itemPath + ".away", away.isPresent());
102:                    if (period != null && groupName != null && key != null && name != null) {
103:                        metrics.add(new EventStatisticMetric(
104:                                period, groupName, key, name, home, away));
105:                    }
106:                }
107:            }
108:        }
109:        if (!problems.isEmpty()) {
110:            return incompatible(evidence, warnings, problems);
111:        }
112:        J5CompletenessReport report = metrics.isEmpty()
113:                ? J5CompletenessReport.emptyValid()
114:                : completeness.report();
115:        return J5ParseResult.parsed(
116:                evidence, new EventStatistics(expectedEventId, metrics), report, warnings);
117:    }
118:
119:    private static J5ParseEvidence evidence(
120:            long snapshotId, RawPayloadEvidence payload, Instant receivedAt) {
121:        if (snapshotId < 1) {
122:            throw new IllegalArgumentException("snapshotId must be positive");
123:        }
124:        return new J5ParseEvidence(
125:                "snapshot:" + snapshotId,
126:                SofascoreEndpointType.EVENT_STATISTICS,
127:                Objects.requireNonNull(payload, "payload").sha256(),
128:                Optional.empty(),
129:                Objects.requireNonNull(receivedAt, "receivedAt"),
130:                PARSER_VERSION);
131:    }
132:
133:    private static J5ParseResult<EventStatistics> incompatible(
134:            J5ParseEvidence evidence,
135:            List<J5ParseWarning> warnings,
136:            List<J5ParseProblem> problems) {
137:        return J5ParseResult.failed(
138:                J5ParseStatus.SCHEMA_INCOMPATIBLE, evidence, warnings, problems);
139:    }
140:
141:    private static J5ParseResult<EventStatistics> failed(
142:            J5ParseStatus status,
143:            J5ParseEvidence evidence,
144:            J5ParseProblem.Code code,
145:            String path,
146:            String message) {
147:        return J5ParseResult.failed(status, evidence, List.of(),
148:                List.of(J5JsonParserSupport.problem(code, path, message)));
149:    }
150:
151:    private static final class Completeness {
152:        private int expected;
153:        private int present;
154:        private final List<String> missing = new ArrayList<>();
155:
156:        void expect(String path, boolean available) {
157:            expected++;
158:            if (available) {
159:                present++;
160:            }
161:            else {
162:                missing.add(path);
163:            }
164:        }
165:
166:        J5CompletenessReport report() {
167:            return J5CompletenessReport.measured(present, expected, missing);
168:        }
169:    }
170:}
